# Check all 8 symmetries for Demo 2
d2_src = [[4,4,4,1,4],
          [4,4,1,4,4],
          [4,1,4,1,1],
          [4,4,1,4,1],
          [4,4,4,4,4]]

d2_out = [[4,1,4,4,4],
          [4,4,1,4,4],
          [1,1,4,1,4],
          [1,4,1,4,4],
          [4,4,4,4,4]]

def rotate90(grid, times=1):
    N = len(grid)
    return [[grid[N-1-j][i] if times%2==1 else grid[N-1-i][j] for i in range(N)] for j in range(N)]

def flip_h(grid):
    return [row[::-1] for row in grid]

def flip_v(grid):
    return grid[::-1]

# Identity, 90, 180, 270 rotations
rots = []
for i in range(4):
    rots.append(rotate90(d2_src, i))
# With horizontal flip
for i in range(4):
    rots.append(flip_h(rotate90(d2_src, i)))

# Check each
for i, r in enumerate(rots):
    if r == d2_out:
        print(f"Found match with {i}: {r}")
    else:
        # Find max matches
        matches = sum(1 for r1, r2 in zip(r, d2_out) if all(a==b for a,b in zip(r1,r2)))
        if matches == len(d2_out):
            print(f"Found match with {i}: {r}")
        else:
            print(f"{i}: max_matches={matches}")

# Also check with 2↔3, 2↔4 swaps on rotations
def swap_c19(grid):
    return [[4 if x==3 else 3 if x==4 else x for x in row] for row in grid]

def swap_c24(grid):
    return [[1 if x==2 else 2 if x==4 else 4 if x==1 else x for x in row] for row in grid]

def swap_c21(grid):
    return [[3 if x==0 else 0 if x==2 else 2 if x==1 else x for x in row] for row in grid]

for name in ['swap_13_24', 'swap_12_34']:
    merged = [swap_c24(r) for r in rots]
    for i, r in enumerate(merged):
        if r == d2_out:
            print(f"Found match with {name} {i}: {r}")
